"""Turbulence models for incompressible flow."""

from typing import Any, Literal
from pydantic import BaseModel
from pybFoam.turbulence import incompressibleTurbulenceModel

from foamadapter.core.plugin_system import PluginSystem
from foamadapter.framework.model import Model


@PluginSystem.register(discriminator_variable="config", discriminator="model_key")
class TurbulenceModel(BaseModel):
    """
    Base class for turbulence models - DISPATCH ONLY.

    This class only provides factory method for type selection.
    All initialization logic is implemented independently by child classes.

    No shared initialization strategy - each model is completely independent.

    Type selection uses composite key to avoid discriminator conflicts:
    - model_key: Composite key (e.g., "RAS_kOmegaSST", "LES_Smagorinsky", "laminar")
    - simulation_type: RAS/LES/laminar
    - turb_model_type: Concrete model (kOmegaSST, Smagorinsky, etc.)

    Note: PluginSystem.register automatically generates plugin_model() which
    is used internally for type selection via discriminated unions.
    """

    model_config = {"arbitrary_types_allowed": True}

    @classmethod
    def create(cls, *, config: dict[str, Any]) -> Any:
        """
        Create turbulence model from config dictionary.

        This method is required by PluginSystem and delegates to plugin_model().
        """
        return cls.plugin_model(config=config)  # type: ignore[attr-defined]

    @classmethod
    def from_file(cls, path: str = "constant/turbulenceProperties") -> Any:
        """
        Factory method to read turbulence properties from OpenFOAM dictionary.

        DISPATCH ONLY - reads simulationType and model type, delegates to plugin_model().

        Returns concrete model instance (kOmegaSSTModel, SmagorinskyModel, etc.)
        based on simulationType and RASModel/LESModel fields.
        """
        import pybFoam as pyf

        turb_dict = pyf.dictionary.read(path)
        simulation_type = turb_dict.get[str]("simulationType")

        # Read concrete model type based on simulation type
        turb_model_type = None
        if simulation_type == "RAS":
            ras_dict = turb_dict.subDict("RAS")
            turb_model_type = ras_dict.get[str]("RASModel")
        elif simulation_type == "LES":
            les_dict = turb_dict.subDict("LES")
            turb_model_type = les_dict.get[str]("LESModel")
        # laminar has no model type

        # Create composite key to avoid discriminator conflicts
        if turb_model_type:
            model_key = f"{simulation_type}_{turb_model_type}"
        else:
            model_key = simulation_type

        config = {
            "model_key": model_key,
            "simulation_type": simulation_type,
            "turb_model_type": turb_model_type,
        }

        # plugin_model is auto-generated by PluginSystem.register decorator
        return cls.plugin_model(config=config)  # type: ignore[attr-defined]


@TurbulenceModel.register
@Model
class kOmegaSSTModel(BaseModel):
    """
    k-omega SST turbulence model - INDEPENDENT IMPLEMENTATION.

    RAS turbulence model with kOmegaSST implementation.
    Instance creation is handled by the setup() method via DAG.
    """

    model_key: Literal["RAS_kOmegaSST"] = "RAS_kOmegaSST"
    simulation_type: Literal["RAS"] = "RAS"
    turb_model_type: Literal["kOmegaSST"] = "kOmegaSST"
    model_config = {"arbitrary_types_allowed": True}
    _instance: Any | None = None

    @property
    def name(self) -> str:
        """Model name for registration in ConfigContext."""
        return "turbulence"

    @Model.build
    def setup(self, mesh: Any) -> list[Any]:
        """
        Setup k-omega SST model initialization.

        Returns LazyInit for DAG-based initialization with proper dependencies.
        """
        from foamadapter.framework.initialization.helpers import model as model_helper

        def create_turbulence_model(ctx: dict[str, Any]) -> Any:
            """Create turbulence model instance."""
            from pybFoam.turbulence import incompressibleTurbulenceModel

            self._instance = incompressibleTurbulenceModel.New(
                ctx["fields.U"], ctx["fields.phi"], ctx["fields.laminarTransport"]
            )
            return self._instance

        return [
            model_helper(
                "turbulence",
                depends_on=["fields.U", "fields.phi", "fields.laminarTransport"],
                create=create_turbulence_model,
            )
        ]

    def operations(self) -> Any:
        """
        Return operations for k-omega SST turbulence model.

        Operations are executed during the solver time loop to update
        turbulence fields (k, omega, nut, etc.).
        """
        from foamadapter.framework.operations import Operation, OperationCollection
        from foamadapter.framework.decorator import decorated_member_functions

        ops = OperationCollection()

        # Collect all decorated operations from this model
        funcs = decorated_member_functions(self)
        for func in funcs:
            ops.add(Operation.create_SeqOp(func))

        return ops


@TurbulenceModel.register
@Model
class kEpsilonModel(BaseModel):
    """
    k-epsilon turbulence model - INDEPENDENT IMPLEMENTATION.

    RAS turbulence model with kEpsilon implementation.
    Instance creation is handled by the setup() method via DAG.
    """

    model_key: Literal["RAS_kEpsilon"] = "RAS_kEpsilon"
    simulation_type: Literal["RAS"] = "RAS"
    turb_model_type: Literal["kEpsilon"] = "kEpsilon"
    model_config = {"arbitrary_types_allowed": True}
    _instance: Any | None = None

    @property
    def name(self) -> str:
        """Model name for registration in ConfigContext."""
        return "turbulence"

    @Model.build
    def setup(self, mesh: Any) -> list[Any]:
        """
        BUILD stage: kEpsilon model's own initialization strategy.

        Instance creation happens here via DAG resolution.
        Returns LazyInit with dependencies (U, phi, transport).
        """
        from foamadapter.framework.initialization.helpers import model as model_helper

        def create_turbulence_model(context: dict[str, Any]) -> Any:
            U = context["fields.U"]
            phi = context["fields.phi"]
            transport = context["fields.laminarTransport"]

            # Use OpenFOAM's runtime selection for now
            # Can be replaced with custom implementation
            instance = incompressibleTurbulenceModel.New(U, phi, transport)
            self._instance = instance
            return instance

        return [
            model_helper(
                "turbulence",
                depends_on=["fields.U", "fields.phi", "fields.laminarTransport"],
                create=create_turbulence_model,
            )
        ]

    def operations(self) -> Any:
        """
        Return operations for k-epsilon turbulence model.

        Operations are executed during the solver time loop to update
        turbulence fields (k, epsilon, nut, etc.).
        """
        from foamadapter.framework.operations import Operation, OperationCollection
        from foamadapter.framework.decorator import decorated_member_functions

        ops = OperationCollection()

        # Collect all decorated operations from this model
        funcs = decorated_member_functions(self)
        for func in funcs:
            ops.add(Operation.create_SeqOp(func))

        return ops

    @Model.operation(operation_number=100)
    def correct_turbulence(self) -> None:
        """Correct turbulence fields (k, epsilon, nut)."""
        if self._instance is not None:
            self._instance.correct()


