@TurbulenceModel.register
@Model
class LaminarModel(BaseModel):
    """
    Laminar (no turbulence) model - INDEPENDENT IMPLEMENTATION.

    Instance creation is handled by the setup() method via DAG.
    """

    model_key: Literal["laminar"] = "laminar"
    simulation_type: Literal["laminar"] = "laminar"
    turb_model_type: None = None
    model_config = {"arbitrary_types_allowed": True}
    _instance: Any | None = None

    @property
    def name(self) -> str:
        """Model name for registration in ConfigContext."""
        return "turbulence"

    @Model.build
    def setup(self, mesh: Any) -> list[Any]:
        """
        BUILD stage: Laminar model's own initialization strategy.

        Instance creation happens here via DAG resolution.
        For laminar flow, typically no turbulence model instance is needed.
        """
        from foamadapter.framework.initialization.helpers import model as model_helper

        def create_turbulence_model(context: dict[str, Any]) -> Any:
            # Laminar = no turbulence model needed
            self._instance = None
            return None

        return [
            model_helper(
                "turbulence",
                depends_on=["fields.U", "fields.phi", "fields.laminarTransport"],
                create=create_turbulence_model,
            )
        ]

    def operations(self) -> Any:
        """
        Return operations for laminar model.

        Laminar model has no turbulence operations (empty collection).
        """
        from foamadapter.framework.operations import OperationCollection

        # Laminar model has no operations
        return OperationCollection()
